import fs from 'fs';
import zlib from 'zlib';
const fp = process.argv[2];
function zstdAll(buf) {
  const MAGIC = Buffer.from([0x28, 0xb5, 0x2f, 0xfd]);
  const idxs = [];
  for (let i = 0; (i = buf.indexOf(MAGIC, i)) >= 0; i += 4) idxs.push(i);
  if (idxs.length <= 1) return zlib.zstdDecompressSync(buf).toString('utf8');
  let out = '';
  for (let k = 0; k < idxs.length; k++) {
    const s = idxs[k], e = k + 1 < idxs.length ? idxs[k + 1] : buf.length;
    try { out += zlib.zstdDecompressSync(buf.subarray(s, e)).toString('utf8'); } catch {}
  }
  return out;
}
function textOf(content) {
  if (content == null) return '';
  if (typeof content === 'string') return content;
  return JSON.stringify(content);
}
const calls = new Map();
const steps = [];
for (const line of zstdAll(fs.readFileSync(fp)).split('\n')) {
  if (!line.trim()) continue;
  let ev; try { ev = JSON.parse(line); } catch { continue; }
  const d = ev.data || {};
  if (ev.type === 'tool/call') {
    let args = d.arguments;
    if (typeof args === 'string') { try { args = JSON.parse(args); } catch { args = {}; } }
    calls.set(d.callId, { name: d.name, turn: d.turn, step: d.step, args });
  } else if (ev.type === 'tool/result') {
    const rec = calls.get(d.message?.toolCallId);
    if (!rec) continue;
    rec.chars = textOf(d.message?.content).length;
    rec.err = !!d.message?.isError;
  } else if (ev.type === 'llm/usage' || ev.type === 'model/usage' || /usage/.test(ev.type || '')) {
    steps.push(ev.type + ' ' + JSON.stringify(d).slice(0, 160));
  }
}
const by = {};
const rows = [];
for (const rec of calls.values()) {
  const chars = rec.chars || 0;
  const b = by[rec.name] || (by[rec.name] = { n: 0, chars: 0 });
  b.n += 1; b.chars += chars;
  rows.push({ ...rec, chars });
}
rows.sort((a, b) => b.chars - a.chars);
console.log('-- by tool --');
for (const [name, b] of Object.entries(by).sort((a, c) => c[1].chars - a[1].chars)) {
  console.log(name, 'calls', b.n, 'chars', b.chars, 'avg', Math.round(b.chars / b.n));
}
console.log('-- top 15 --');
for (const r of rows.slice(0, 15)) {
  const a = r.args || {};
  const target = a.file_path || a.path || a.pattern || a.command || a.tool || a.name || '';
  console.log(r.chars, r.err ? 'ERR' : 'ok', r.turn + '.' + r.step, r.name, String(target).replace(/\s+/g, ' ').slice(0, 90));
}
console.log('-- usage events', steps.length);
for (const s of steps.slice(0, 6)) console.log(s);
console.log('totalChars', rows.reduce((s, r) => s + r.chars, 0));

