const GREP_MATCH = /(?:^|\n)\s*(?:Line\s+)?\d+:/g;

/** grep 超过 30 条、read 超过 500 行、skill 正文超过 2500 字时截断。未超限返回 null。 */
function cappedText(toolName, text) {
  if (toolName === "grep") {
    const marks = [...text.matchAll(GREP_MATCH)];
    if (marks.length <= 30) return null;
    const cut = marks[30].index;
    return text.slice(0, cut)
      + "\n[token-guard] grep 已超过 30 条，其余已截断。请缩小 path 或 pattern，不要继续扩大搜索范围。";
  }
  if (toolName === "read") {
    const lines = text.split("\n");
    if (lines.length <= 500) return null;
    return lines.slice(0, 500).join("\n")
      + "\n[token-guard] read 已超过 500 行，其余已截断。请用 offset/limit 续读，或改用 grep 定位。";
